  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "A close CUMI-101 analogue with the same butylpiperazine linker penetrated the BBB in baboon PET, with regional brain uptake matching 5-HT1A receptor distribution.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "FECUMI-101, a fluoroethyl analogue sharing the same triazinedione-butylpiperazine scaffold, effectively crossed the BBB in baboon PET studies.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "The related [123I]-BPB tracer, containing a methoxyphenylpiperazine-butylamide motif, showed high mouse brain uptake (4.99 %ID/g at 10 min), indicating ready BBB passage.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "NGB 2904, a butylpiperazine aryl amide with a dichlorophenylpiperazine group, entered the brain quickly and demonstrated high brain penetration after IV administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A [11C]methoxyphenylpiperazine-butyl triazinedione analogue penetrated the BBB in baboon PET, confirming CNS access for this scaffold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer analogues sharing the butylpiperazine-arylpiperazine CNS scaffold demonstrate BBB penetration in PET, biodistribution, or IV brain-uptake studies; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "No explicit efflux-transporter data for the query.",
    "Most evidence is qualitative PET or biodistribution rather than quantitative unbound brain exposure."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

